    pillarLabel: "1031 Education",
    scheduledISO: "2026-06-22T08:00:00",
    hashtags: "#Reverse1031 #1031Exchange #RealEstateInvesting #CapitalGainsDeferral #TaxStrategy",
    visualDescription: "Two stacked timelines: top labeled 'Forward 1031: Sell first, then buy.' Bottom labeled 'Reverse 1031: Buy first, then sell.' with the buy-first sequence highlighted. Includes a small 'EAT holds title' callout. Brand-colored.",
